import json
from decimal import Decimal

from.database_client import get_dynamodb_client


def fetch_document(document_id, config=None):
    config = config or {}
    client = get_dynamodb_client(config)
    response = client.get_item(
        TableName=config["table_name"],
        Key={config.get("key_field", "id"): {"S": document_id}}
    )
    item = response.get("Item")
    if item:
        return json.loads(json.dumps(item, default=str))
    return None

from.database_client import get_dynamodb_client


def query_documents(field_name, field_value, config=None):
    config = config or {}
    client = get_dynamodb_client(config)
    response = client.query(
        TableName=config["table_name"],
        KeyConditionExpression="#field_name = :field_value",
        ExpressionAttributeNames={"#field_name": field_name},
        ExpressionAttributeValues={":field_value": {"S": field_value}}
    )
    items = response.get("Items", [])
    return [item for item in items]

from.database_client import get_dynamodb_client


def conditional_update(document_id, update_expression, expression_attribute_values, config=None):
    config = config or {}
    client = get_dynamodb_client(config)
    response = client.update_item(
        TableName=config["table_name"],
        Key={config.get("key_field", "id"): {"S": document_id}},
        UpdateExpression=update_expression,
        ExpressionAttributeValues=expression_attribute_values,
        ReturnValues="ALL_NEW"
    )
    return response.get("Attributes")

import boto3


def get_dynamodb_client(config):
    return boto3.client("dynamodb", region_name=config.get("region"))

def summarize_records(records):
    summary = {}
    for record in records:
        for key, value in record.items():
            if key not in summary:
                summary[key] = []
            summary[key].append(value)
    return summary

import re


def check_unsafe_content(text):
    unsafe_patterns = [
        r"<script>.*?</script>",
        r"<iframe>.*?</iframe>"
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, text):
            return True
    return False

import boto3


def export_records_to_s3(records, bucket_name, prefix):
    s3 = boto3.client('s3')
    for i, record in enumerate(records):
        key = f"{prefix}/{i}.json"
        s3.put_object(Bucket=bucket_name, Key=key, Body=json.dumps(record))
